-- G26: append-only empirical monitoring and review proposals; no silent catalog mutation.
create table public.empirical_metric_definitions(metric_key text primary key,entity_type text not null,minimum_sample integer not null check(minimum_sample>0),calculation_version text not null,thresholds jsonb not null,created_at timestamptz not null default now());
insert into public.empirical_metric_definitions values('passage_success_calibration','passage',30,'1.0.0','{"zone":[0.75,0.85],"max_drift":0.08}',now()),('question_quality','question',50,'1.0.0','{"min_discrimination":0.1}',now()),('edge_predictive_lift','graph_edge',100,'1.0.0','{"min_lift":0.05}',now()),('diagnostic_calibration','diagnostic',50,'1.0.0','{"max_mae":0.15}',now()),('quiz_calibration','quiz',50,'1.0.0','{"max_mae":0.15}',now()),('retrieval_effectiveness','retrieval',50,'1.0.0','{}',now()),('retention','course',30,'1.0.0','{}',now());
create table public.empirical_metric_snapshots(id uuid primary key default gen_random_uuid(),metric_key text not null references public.empirical_metric_definitions(metric_key) on delete restrict,entity_type text not null,entity_id uuid,learner_mode text,content_type text,sample_size integer not null check(sample_size>=0),status text not null check(status in('insufficient_evidence','active')),metric_payload jsonb not null,calculation_version text not null,window_start timestamptz,window_end timestamptz,created_at timestamptz not null default now());
create table public.empirical_adjustment_proposals(id uuid primary key default gen_random_uuid(),metric_snapshot_id uuid not null references public.empirical_metric_snapshots(id) on delete restrict,target_type text not null,target_id uuid not null,current_value numeric not null,proposed_value numeric not null,adjustment numeric not null check(adjustment between -.1 and .1),status text not null default 'pending_review' check(status in('pending_review','approved','rejected','superseded')),rationale jsonb not null,created_at timestamptz not null default now(),reviewed_at timestamptz,reviewed_by uuid references public.profiles(id) on delete set null);
create table public.empirical_review_events(id uuid primary key default gen_random_uuid(),metric_snapshot_id uuid not null references public.empirical_metric_snapshots(id) on delete restrict,event_type text not null check(event_type in('empirical_anomaly','drift','no_lift','retention_gap','operational_anomaly')),reason_key text not null,explanation jsonb not null,status text not null default 'open' check(status in('open','investigating','resolved','dismissed')),created_at timestamptz not null default now(),resolved_at timestamptz);
alter table public.empirical_metric_definitions enable row level security;alter table public.empirical_metric_snapshots enable row level security;alter table public.empirical_adjustment_proposals enable row level security;alter table public.empirical_review_events enable row level security;create policy metric_definitions_staff_read on public.empirical_metric_definitions for select using(public.is_staff());create policy metric_snapshots_staff_read on public.empirical_metric_snapshots for select using(public.is_staff());create policy adjustment_proposals_staff_read on public.empirical_adjustment_proposals for select using(public.is_staff());create policy empirical_events_staff_read on public.empirical_review_events for select using(public.is_staff());grant select on public.empirical_metric_definitions,public.empirical_metric_snapshots,public.empirical_adjustment_proposals,public.empirical_review_events to authenticated;
comment on table public.empirical_adjustment_proposals is 'Bounded proposals only. Monitoring cannot silently mutate answer keys, historical evidence, mastery, or published taxonomy/lexical releases.';
